#!/usr/bin/env node
/**
 * CombatSense Edge — release.rpk 校验脚本
 *
 * 验证 release/ 目录下的 .rpk 文件：
 * 1. 恰好存在一个 .rpk 文件
 * 2. 文件为有效 ZIP 格式
 * 3. ZIP 内包含 manifest.json
 * 4. 包名为 com.openvela.combatsense
 * 5. versionName 为 1.0.0
 *
 * 无外部依赖，仅使用 Node.js 内置模块。
 * Run: node scripts/verify-release.js
 * Exit 0 = pass, Exit 1 = fail
 */

'use strict';

var fs = require('fs');
var path = require('path');

var RELEASE_DIR = path.join(__dirname, '..', 'release');
var EXPECTED_PACKAGE = 'com.openvela.combatsense';
var EXPECTED_VERSION = '1.0.0';
var passed = 0;
var failed = 0;
var errors = [];

function assert(cond, msg) {
  if (cond) {
    passed++;
    console.log('  PASS: ' + msg);
  } else {
    failed++;
    errors.push(msg);
    console.error('  FAIL: ' + msg);
  }
}

// ---- 1. Check release directory exists ----
console.log('\n[1] Release directory');
assert(fs.existsSync(RELEASE_DIR), 'release/ directory exists');

if (!fs.existsSync(RELEASE_DIR)) {
  console.log('\n========================================');
  console.log('Passed: ' + passed + '  Failed: ' + failed);
  console.log('ABORT: release/ directory missing');
  process.exit(1);
}

// ---- 2. Find .rpk files ----
console.log('\n[2] RPK file count');
var rpkFiles = fs.readdirSync(RELEASE_DIR).filter(function (f) {
  return f.endsWith('.rpk');
});

assert(rpkFiles.length === 1, 'exactly one .rpk file found (got ' + rpkFiles.length + ')');

if (rpkFiles.length !== 1) {
  console.log('\n========================================');
  console.log('Passed: ' + passed + '  Failed: ' + failed);
  console.log('ABORT: expected exactly one .rpk file');
  process.exit(1);
}

var rpkPath = path.join(RELEASE_DIR, rpkFiles[0]);
console.log('  Found: ' + rpkFiles[0]);

// ---- 3. Check file size ----
console.log('\n[3] File size');
var stat = fs.statSync(rpkPath);
assert(stat.size > 0, 'RPK file size > 0 bytes (' + stat.size + ' bytes)');

// ---- 4. Verify ZIP integrity ----
console.log('\n[4] ZIP integrity');
var zipBuf = fs.readFileSync(rpkPath);

// Check ZIP local file header signature (PK\x03\x04)
var isZip = zipBuf[0] === 0x50 && zipBuf[1] === 0x4B &&
            zipBuf[2] === 0x03 && zipBuf[3] === 0x04;
assert(isZip, 'RPK is a valid ZIP file (PK header)');

if (!isZip) {
  console.log('\n========================================');
  console.log('Passed: ' + passed + '  Failed: ' + failed);
  console.log('ABORT: not a valid ZIP');
  process.exit(1);
}

// ---- 5. Extract and check manifest.json ----
console.log('\n[5] Manifest extraction');
try {
  // Use Node.js built-in zlib to parse ZIP
  // Simple approach: search for manifest.json in the ZIP file list
  var content = zipBuf.toString('latin1');

  // Find End of Central Directory record
  var eocdPos = content.lastIndexOf('PK\x05\x06');
  assert(eocdPos >= 0, 'ZIP End of Central Directory found');

  if (eocdPos < 0) {
    console.log('\n========================================');
    console.log('Passed: ' + passed + '  Failed: ' + failed);
    process.exit(1);
  }

  // Parse EOCD to get central directory offset
  var cdOffset = zipBuf.readUInt32LE(eocdPos + 16);
  var cdSize = zipBuf.readUInt32LE(eocdPos + 12);
  var numEntries = zipBuf.readUInt16LE(eocdPos + 10);

  console.log('  ZIP entries: ' + numEntries);
  assert(numEntries > 0, 'ZIP contains at least one entry');

  // Walk central directory entries to find manifest.json
  var offset = cdOffset;
  var manifestFound = false;
  var manifestContent = null;

  for (var i = 0; i < numEntries; i++) {
    var sig = zipBuf.readUInt32LE(offset);
    if (sig !== 0x02014B50) break; // Central directory header

    var nameLen = zipBuf.readUInt16LE(offset + 28);
    var extraLen = zipBuf.readUInt16LE(offset + 30);
    var commentLen = zipBuf.readUInt16LE(offset + 32);
    var localOffset = zipBuf.readUInt32LE(offset + 42);
    var fileName = zipBuf.toString('utf8', offset + 46, offset + 46 + nameLen);

    if (fileName === 'manifest.json') {
      manifestFound = true;

      // Read local file header to get compressed size and offset
      var lsig = zipBuf.readUInt32LE(localOffset);
      if (lsig === 0x04034B50) {
        var lNameLen = zipBuf.readUInt16LE(localOffset + 26);
        var lExtraLen = zipBuf.readUInt16LE(localOffset + 28);
        var compSize = zipBuf.readUInt32LE(localOffset + 18);
        var dataOffset = localOffset + 30 + lNameLen + lExtraLen;

        if (compSize > 0) {
          manifestContent = zipBuf.toString('utf8', dataOffset, dataOffset + compSize);
        }
      }
      break;
    }

    offset += 46 + nameLen + extraLen + commentLen;
  }

  assert(manifestFound, 'manifest.json found in ZIP');

  if (!manifestFound || !manifestContent) {
    console.log('\n========================================');
    console.log('Passed: ' + passed + '  Failed: ' + failed);
    process.exit(1);
  }

  // ---- 6. Parse and validate manifest ----
  console.log('\n[6] Manifest validation');
  var manifest = JSON.parse(manifestContent);

  assert(manifest.package === EXPECTED_PACKAGE,
    'package name is ' + EXPECTED_PACKAGE + ' (got ' + manifest.package + ')');
  assert(manifest.versionName === EXPECTED_VERSION,
    'versionName is ' + EXPECTED_VERSION + ' (got ' + manifest.versionName + ')');
  assert(manifest.name, 'manifest has name field');

} catch (e) {
  assert(false, 'ZIP parsing failed: ' + e.message);
}

// ---- Summary ----
console.log('\n========================================');
console.log('Passed: ' + passed + '  Failed: ' + failed);
if (failed > 0) {
  console.log('\nFailures:');
  errors.forEach(function (e) { console.log('  - ' + e); });
  process.exit(1);
} else {
  console.log('release.rpk verification passed.');
  process.exit(0);
}

